insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'oth_char_v1'
from (values
('120.3.b.1.A ',1,'Ben chooses to pick up his toys, so his room is neat. What led to his action?','["his own choice", "a TV show", "the weather", "a loud noise"]'::jsonb,0,'A personal choice leads to a personal action.','original'),
('120.3.b.1.A ',2,'Which sentence shows that a choice leads to an action?','["My shoes are red.", "I chose to share, so I handed my friend a crayon.", "It is raining outside.", "The bus is yellow."]'::jsonb,1,'The choice came first and the action followed.','original'),
('120.3.b.1.B ',1,'What does it mean to be trustworthy?','["You always win games.", "You never talk.", "People can count on you to do what is right.", "You are the tallest."]'::jsonb,2,'Trustworthy people can be depended on.','original'),
('120.3.b.1.B ',2,'Mia says she will feed the class fish and she does it every day. Mia is:','["silly", "shy", "bossy", "trustworthy"]'::jsonb,3,'Doing what you promise makes you trustworthy.','original'),
('120.3.b.1.C ',2,'Which action builds trust?','["telling the truth even when it is hard", "saying you did a job you did not do", "hiding a mistake", "taking a toy without asking"]'::jsonb,0,'Honesty builds trust.','original'),
('120.3.b.1.C ',2,'Being punctual means:','["running fast", "arriving on time", "arriving late", "talking loudly"]'::jsonb,1,'Punctual means on time.','original'),
('120.3.b.2.A ',2,'Sam feels sad, so he walks away quietly. How did his feeling affect his action?','["Feelings never matter.", "His shoes made him walk.", "His feeling changed what he did.", "He had no feeling."]'::jsonb,2,'Feelings and beliefs influence actions.','original'),
('120.3.b.2.A ',2,'Lia believes it is good to help, so she helps a classmate pick up books. This shows that:','["helping is a game", "books are heavy", "beliefs are silly", "beliefs guide actions"]'::jsonb,3,'What we believe can lead to what we do.','original'),
('120.3.b.2.B ',1,'What should you do before you speak or act when you feel upset?','["stop and think", "run away", "grab something", "shout first"]'::jsonb,0,'Stopping to think helps you choose well.','original'),
('120.3.b.2.B ',2,'Which is a good way to choose before you act?','["copy what a stranger does", "take a deep breath and think about what could happen", "wait for someone to dare you", "do it right now"]'::jsonb,1,'Thinking ahead leads to better choices.','original'),
('120.3.b.2.C ',2,'Self-control means:','["doing whatever you want", "being the loudest", "stopping yourself from doing something you should not do", "never feeling anything"]'::jsonb,2,'Self-control is managing your own actions.','original'),
('120.3.b.2.C ',2,'When is self-control most important?','["when you eat lunch alone", "when you are asleep", "when you are alone and quiet", "when you want to grab a toy someone else is using"]'::jsonb,3,'Self-control helps when a strong want could cause a problem.','original'),
('120.3.b.3.A ',2,'Which shows patience?','["waiting quietly in line for your turn", "taking the toy back", "pushing to the front", "yelling at the teacher"]'::jsonb,0,'Patience is waiting calmly.','original'),
('120.3.b.3.A ',2,'Patience means:','["hurrying others", "staying calm while you wait", "complaining loudly", "giving up fast"]'::jsonb,1,'Patience is calm waiting.','original'),
('120.3.b.3.B',2,'Which action shows kindness?','["laughing at a mistake", "ignoring someone who needs help", "helping a new student find the cafeteria", "leaving someone out"]'::jsonb,2,'Kind actions help or care for others.','original'),
('120.3.b.3.B',1,'Jo shares her snack with a friend who forgot lunch. Jo is being:','["rude", "careless", "selfish", "kind"]'::jsonb,3,'Sharing to help others is kind.','original'),
('120.3.b.4.A',2,'Which is fair?','["everyone gets a turn on the swing", "no one gets a turn", "only the biggest kids play", "the same two kids always go first"]'::jsonb,0,'Fairness means treating everyone equally.','original'),
('120.3.b.4.A',2,'Two kids both want the ball. What is a fair way to decide?','["the louder kid wins", "take turns", "the bigger kid takes it", "hide the ball"]'::jsonb,1,'Taking turns is a fair rule.','original'),
('120.3.b.4.B ',2,'Patriotism is:','["fear of your country", "love of games", "love and pride for your country", "dislike of rules"]'::jsonb,2,'A patriot cares about their country.','original'),
('120.3.b.4.B ',2,'Which is a way to show patriotism?','["eating lunch", "painting a picture of a cat", "walking to class", "saying the Pledge of Allegiance"]'::jsonb,3,'Pledges and honoring the flag show love of country.','original'),
('120.3.b.4.C ',2,'Which shows respect and courtesy?','["saying please and thank you", "interrupting", "calling names", "rolling your eyes"]'::jsonb,0,'Polite words show respect.','original'),
('120.3.b.4.C ',2,'Why is it important to show respect to others?','["It is only for adults.", "It helps everyone feel safe and valued.", "It keeps you from learning.", "It makes you taller."]'::jsonb,1,'Respect creates a kind community.','original'),
('120.3.b.4.D ',2,'A good citizen is someone who:','["breaks rules", "only thinks of themselves", "helps their community and follows rules", "ignores neighbors"]'::jsonb,2,'Good citizens care and take part.','original'),
('120.3.b.4.D ',2,'Which is something a good citizen does?','["teases others", "leaves trash on the ground", "skips voting when old enough", "picks up trash at the park"]'::jsonb,3,'Citizens help keep the community nice.','original'),
('120.5.b.1.A ',2,'Reliability means that a person:','["can be counted on to do what they say", "is sometimes late", "changes plans all the time", "hides the truth"]'::jsonb,0,'A reliable person is dependable.','original'),
('120.5.b.1.A ',3,'Loyalty is shown when someone:','["leaves a friend when it is easier", "stays true to a friend or group, even when it is hard", "tells secrets for fun", "only likes winners"]'::jsonb,1,'Loyalty means staying faithful.','original'),
('120.5.b.1.B',2,'Which is a good strategy for being punctual?','["waiting for others to remind you", "leaving at the last second", "setting an alarm and packing your bag the night before", "ignoring the clock"]'::jsonb,2,'Planning ahead helps you be on time.','original'),
('120.5.b.1.B',3,'If you break a classmate''s pencil by mistake, the honest choice is to:','["blame another student", "hide it", "say nothing and hope no one knows", "tell the classmate what happened"]'::jsonb,3,'Honesty means telling the truth.','original'),
('120.5.b.1.C ',3,'Which is an example of unethical behavior?','["copying a classmate''s test answers", "studying with a friend", "returning a lost wallet", "asking a teacher for help"]'::jsonb,0,'Cheating is dishonest and unfair.','original'),
('120.5.b.1.C ',3,'Unethical behavior is:','["a school subject", "behavior that is dishonest or breaks moral rules", "always a mistake in math", "a type of exercise"]'::jsonb,1,'Ethics is about right and wrong.','original'),
('120.5.b.2.A ',3,'Being responsible for your decisions means:','["blaming others", "pretending nothing happened", "accepting the results of your choices", "letting someone else fix it"]'::jsonb,2,'Responsible people own their choices.','original'),
('120.5.b.2.A ',3,'Dev forgot his homework because he played games. A responsible reply is:','["It was my brother''s fault.", "Homework is silly.", "The dog ate it.", "I made a choice, and I will fix it."]'::jsonb,3,'He takes ownership.','original'),
('120.5.b.2.B',3,'A positive consequence of studying every night is:','["better grades", "less sleep", "more homework", "a lost book"]'::jsonb,0,'Good choices can bring positive results.','original'),
('120.5.b.2.B',3,'A negative consequence of leaving your bike outside in the rain is:','["it gets cleaner forever", "it may rust", "it gets stronger", "it gets faster"]'::jsonb,1,'Poor choices can bring negative results.','original'),
('120.5.b.2.C',3,'Which is a way to practice self-control when you are angry?','["yelling at a friend", "slamming a door", "counting to ten before you answer", "throwing a book"]'::jsonb,2,'Pausing helps you control a reaction.','original'),
('120.5.b.2.C',3,'When tempted to eat all the cookies, self-control means:','["hiding them", "eating them all", "blaming the cookie jar", "taking only your share"]'::jsonb,3,'Self-control is saying no to a strong urge.','original'),
('120.5.b.2.D',3,'Being accountable means:','["you explain and answer for your actions", "you never make mistakes", "you let others decide for you", "you avoid the topic"]'::jsonb,0,'Accountable people answer for what they do.','original'),
('120.5.b.2.D',4,'How are responsibility and accountability related?','["Responsibility is only for adults.", "A responsible person does a job, and an accountable person answers for how it went.", "Accountability is only for teachers.", "They mean the opposite."]'::jsonb,1,'Both involve ownership of actions.','original'),
('120.5.b.3.A ',3,'How can feelings affect decisions?','["Feelings are always correct.", "Feelings only matter in math.", "Anger might make a person choose quickly without thinking.", "Feelings never change choices."]'::jsonb,2,'Strong feelings can steer behavior.','original'),
('120.5.b.3.A ',3,'Zoe feels nervous, so she practices before the talk. Her feeling led to:','["a broken rule", "a mean joke", "a lost game", "a helpful decision"]'::jsonb,3,'Feelings can lead to good or poor choices.','original'),
('120.5.b.3.B ',3,'Which shows compassion?','["comforting a classmate who dropped her lunch", "laughing", "walking past", "taking the lunch"]'::jsonb,0,'Compassion means caring about someone''s trouble.','original'),
('120.5.b.3.B ',3,'Consideration means:','["thinking only of yourself", "thinking about how your actions affect others", "being the center of attention", "hurrying through work"]'::jsonb,1,'A considerate person thinks of others.','original'),
('120.5.b.3.C',4,'How are empathy and charity connected?','["Charity is only for rich people.", "They have nothing in common.", "Understanding someone''s need can lead us to give or help.", "Empathy means ignoring a need."]'::jsonb,2,'Empathy often inspires charitable acts.','original'),
('120.5.b.4.A',3,'What is the difference between gratitude and courtesy?','["Courtesy is a kind of math.", "Gratitude is rude.", "They mean exactly the same thing.", "Gratitude is feeling thankful, and courtesy is polite behavior."]'::jsonb,3,'Both are positive, but one is a feeling and one is behavior.','original'),
('120.5.b.4.A',3,'Saying thank you when someone helps shows:','["gratitude", "anger", "greed", "boredom"]'::jsonb,0,'Thanking others expresses gratitude.','original'),
('120.5.b.4.B ',4,'Fairness means treating people equally. Justice means:','["ignoring the rules", "making sure people are treated according to what is right and lawful", "letting the strongest win", "favoring friends"]'::jsonb,1,'Justice is about right outcomes under fair rules.','original'),
('120.5.b.4.B ',4,'A referee calls fouls the same for both teams. This is an example of:','["guessing", "cheating", "fairness", "favoritism"]'::jsonb,2,'Equal treatment is fair.','original'),
('120.5.b.4.C ',3,'Why is it important to obey laws and rules?','["They make life boring.", "They only apply to others.", "They are hard to read.", "They keep people safe and help communities work well."]'::jsonb,3,'Rules protect and organize us.','original'),
('120.5.b.4.C ',3,'A school rule says to walk in the hallway. Following it helps:','["keep everyone from getting hurt", "make the floor shine", "stop the bell", "slow down the clock"]'::jsonb,0,'Rules prevent accidents.','original'),
('120.7.b.1.A ',3,'A person who is reliable and loyal:','["avoids friends", "keeps promises and sticks with friends through difficulty", "breaks promises when it suits them", "only helps when rewarded"]'::jsonb,1,'Reliability and loyalty build strong relationships.','original'),
('120.7.b.1.A ',3,'Which describes loyalty?','["joining in the gossip", "moving to a new group", "defending a friend who is being spoken about unfairly", "ignoring your friend''s problem"]'::jsonb,2,'Loyalty means standing with someone.','original'),
('120.7.b.1.B ',3,'Integrity means:','["avoiding consequences", "following the crowd", "doing right only to get praise", "doing the right thing even when no one is watching"]'::jsonb,3,'Integrity is consistent honesty and moral strength.','original'),
('120.7.b.1.B ',4,'A cashier gives you extra change by mistake and you return it. This is an example of:','["integrity", "luck", "greed", "avoidance"]'::jsonb,0,'Returning the extra money is honest.','original'),
('120.7.b.1.C ',3,'One benefit of being trustworthy is that:','["people avoid you", "people rely on you and trust you with more responsibility", "you get everything for free", "you never make mistakes"]'::jsonb,1,'Trust opens doors to responsibility.','original'),
('120.7.b.1.C ',4,'Why does trustworthiness help a team project?','["It lets one person do all the work.", "It guarantees a perfect grade.", "Group members count on each person to do their part.", "It removes the need for planning."]'::jsonb,2,'A reliable team shares the load.','original'),
('120.7.b.1.D ',3,'Which action shows trustworthiness at home?','["skipping duties", "blaming a sibling", "hiding broken items", "completing chores without being reminded"]'::jsonb,3,'Dependability builds family trust.','original'),
('120.7.b.1.D ',3,'At school, trustworthiness is shown by:','["turning in your own work honestly", "copying a friend''s essay", "sharing answers on a test", "skipping assignments"]'::jsonb,0,'Honest effort shows trust.','original'),
('120.7.b.2.A ',4,'How can positive beliefs about yourself build responsibility?','["They remove all mistakes.", "Believing you can handle a task makes you more willing to take it on.", "They make you avoid work.", "They have no effect on actions."]'::jsonb,1,'Self-belief encourages ownership.','original'),
('120.7.b.2.A ',3,'Which thought is most likely to support responsible behavior?','["It does not matter what I do.", "Someone else will handle it.", "I can follow through on what I committed to.", "Rules are optional."]'::jsonb,2,'Positive self-talk builds responsibility.','original'),
('120.7.b.2.B ',3,'A good role model for accountability is someone who:','["hides errors", "avoids all risks", "blames others", "admits mistakes and fixes them"]'::jsonb,3,'Accountable role models own their actions.','original'),
('120.7.b.2.B ',3,'Which person shows accountability?','["a coach who says, I made the wrong call and we will learn from it", "a coach who ignores the loss", "a coach who says it was the players'' fault", "a coach who quits"]'::jsonb,0,'Owning mistakes is accountability.','original'),
('120.7.b.2.C ',3,'One benefit of practicing self-control is that:','["you never feel emotions", "you can think before reacting and avoid regret", "you never need help", "you always win"]'::jsonb,1,'Self-control improves choices.','original'),
('120.7.b.2.C ',3,'Which situation calls for self-control?','["eating lunch quietly", "walking to class", "getting an unfair grade and wanting to lash out", "reading a book"]'::jsonb,2,'Strong emotions test self-control.','original'),
('120.7.b.2.D ',4,'Compare responsible and irresponsible behavior: responsible behavior usually leads to:','["the same results", "no results at all", "punishment for everyone", "trust and good results, while irresponsible behavior leads to problems"]'::jsonb,3,'Consequences differ based on behavior.','original'),
('120.7.b.2.D ',3,'A student who turns work in on time and a student who does not will likely differ in:','["the consequences they face", "their age", "their hobbies", "their height"]'::jsonb,0,'Responsible choices bring different results.','original'),
('120.7.b.3.A ',3,'Evaluating your attitudes means:','["deciding you cannot change", "looking honestly at how you think and feel about yourself and others", "ignoring your thoughts", "blaming other people"]'::jsonb,1,'Self-reflection helps growth.','original'),
('120.7.b.3.A ',4,'A growth mindset is the belief that:','["abilities never change", "mistakes mean failure", "abilities can improve with effort", "only talent matters"]'::jsonb,2,'A growth mindset supports learning.','original'),
('120.7.b.3.B',3,'Making decisions while angry can:','["have no effect", "make others trust you more", "always improve friendships", "harm relationships with others"]'::jsonb,3,'Decisions made in anger can hurt others.','original'),
('120.7.b.3.B',4,'How can a person improve their relationships through their behavior?','["by thinking about feelings and choosing respectful actions", "by acting on every impulse", "by avoiding people", "by ignoring feelings"]'::jsonb,0,'Thoughtful choices strengthen relationships.','original'),
('120.7.b.3.C',3,'Which is an example of empathy through kindness?','["staring at them", "sitting with a classmate who seems lonely", "avoiding them", "teasing them"]'::jsonb,1,'Empathy shows up in caring actions.','original'),
('120.7.b.3.C',4,'A student collects canned food for families in need. This is an example of:','["self-promotion", "greed", "charity", "avoidance"]'::jsonb,2,'Giving to those in need is charity.','original'),
('120.7.b.4.A ',3,'One role of a citizen is to:','["ignore laws", "refuse to vote", "avoid helping", "follow laws and take part in the community"]'::jsonb,3,'Citizens have rights and duties.','original'),
('120.7.b.4.A ',4,'Which is a responsibility of citizenship?','["paying taxes", "skipping jury duty always", "breaking curfews", "avoiding all school"]'::jsonb,0,'Taxes support public services.','original'),
('120.7.b.4.B ',3,'How can personal actions affect how others see you?','["Only appearance matters.", "People form opinions based on what you do.", "Only grades matter.", "They do not."]'::jsonb,1,'Behavior shapes reputation.','original'),
('120.7.b.4.B ',3,'Posting something unkind online may cause others to see you as:','["generous", "wise", "disrespectful", "reliable"]'::jsonb,2,'Actions are noticed and judged.','original'),
('120.7.b.4.C ',4,'How are justice, fairness and freedom related?','["They only apply to games.", "They have nothing in common.", "They are opposites.", "They all support treating people rightly and protecting their rights."]'::jsonb,3,'They are connected ideals in a society.','original'),
('120.7.b.4.C ',4,'A society that protects freedom and applies laws fairly is working toward:','["justice", "secrecy", "chaos", "bias"]'::jsonb,0,'Fair laws and freedom support justice.','original'),
('120.7.b.4.D ',3,'Which is a good conflict-resolution strategy?','["walking away forever", "listening to the other person and looking for a compromise", "yelling louder", "spreading rumors"]'::jsonb,1,'Listening and compromise settle conflicts.','original'),
('120.7.b.4.D ',3,'Using I statements like I feel upset when plans change helps because:','["it ends the conversation", "it proves you are right", "it explains your feelings without blaming", "it hides your feelings"]'::jsonb,2,'I statements reduce blame.','original'),
('120.9.b.1.A',4,'The power to make decisions relates to personal actions because:','["decisions have no effect", "other people always choose for you", "actions happen by themselves", "the choices you make lead to what you do and what happens next"]'::jsonb,3,'Decisions drive actions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Other Texas Essential Knowledge and Skills' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
