from (values
('120.9.b.1.A',4,'Choosing to study each night instead of skipping shows that:','["your decisions shape your results", "effort is pointless", "luck decides all outcomes", "only teachers matter"]'::jsonb,0,'Decisions lead to outcomes.','original'),
('120.9.b.1.B ',4,'When a leader admits an error and corrects it, that leader shows:','["disinterest", "integrity and ethical leadership", "greed", "weakness only"]'::jsonb,1,'Ethical leaders model responsibility.','original'),
('120.9.b.1.B ',4,'Which action by a public official best shows integrity?','["accepting a hidden payment", "hiding a conflict of interest", "refusing a gift meant to influence a decision", "misleading the public"]'::jsonb,2,'Integrity means avoiding corruption.','original'),
('120.9.b.1.C ',4,'A legal consequence of unethical behavior such as fraud may be:','["a school holiday", "a promotion always", "a free ticket", "fines or jail time"]'::jsonb,3,'Unethical acts can break laws.','original'),
('120.9.b.1.C ',4,'A social consequence of lying repeatedly is that:','["others may stop trusting you", "nothing changes", "friends increase", "more people trust you"]'::jsonb,0,'Dishonesty damages relationships.','original'),
('120.9.b.2.A ',3,'A role model for accountability is a person who:','["avoids hard tasks", "takes responsibility for their words and actions", "never explains choices", "blames others for errors"]'::jsonb,1,'Accountable role models own results.','original'),
('120.9.b.2.A ',4,'Which public figure example best shows accountability?','["a leader who denies everything", "a leader who deletes evidence", "a leader who publicly apologizes and repairs a harm", "a leader who blames staff"]'::jsonb,2,'Apologies and repair show accountability.','original'),
('120.9.b.2.B ',4,'Which is a real-world example of taking personal responsibility?','["a driver who lies to police", "a driver who leaves the scene", "a driver who blames the weather", "a driver who pays for the damage after a fender bender"]'::jsonb,3,'Paying for damage you caused is responsibility.','original'),
('120.9.b.2.B ',3,'A student who forgets a deadline and tells the teacher the truth is showing:','["personal responsibility", "avoidance", "entitlement", "deception"]'::jsonb,0,'Facing a mistake honestly is responsible.','original'),
('120.9.b.2.C ',4,'Which is an effective strategy for self-control during a stressful exam week?','["avoiding all work", "making a schedule and taking short breaks", "blaming teachers", "staying up all night"]'::jsonb,1,'Planning supports self-control.','original'),
('120.9.b.2.C ',4,'When feeling an urge to react angrily online, the best strategy is to:','["post immediately", "delete your account", "pause and wait before posting", "argue until you win"]'::jsonb,2,'Pausing reduces regrettable posts.','original'),
('120.9.b.2.D ',3,'Perseverance is:','["changing goals daily", "avoiding goals", "quitting when it gets hard", "continuing to work toward a goal despite difficulties"]'::jsonb,3,'Perseverance means sticking with it.','original'),
('120.9.b.2.D ',4,'Which strategy demonstrates perseverance?','["breaking a big goal into smaller steps and keeping at them", "waiting for someone else", "skipping practice", "giving up after one failure"]'::jsonb,0,'Steady steps help you persist.','original'),
('120.9.b.3.A ',4,'Evaluating your attitudes about yourself and others can help you:','["ignore other views", "notice biases and improve how you treat people", "stay unchanged", "avoid feedback"]'::jsonb,1,'Self-evaluation encourages growth.','original'),
('120.9.b.3.A ',4,'A person who assumes all people from a group are the same is showing:','["integrity", "perseverance", "a stereotype", "empathy"]'::jsonb,2,'A stereotype is an oversimplified belief.','original'),
('120.9.b.3.B ',4,'How can feelings and decisions affect relationships in society?','["They never matter in groups.", "They only matter at home.", "They only affect strangers.", "Choices made from strong emotions can build or damage trust with others."]'::jsonb,3,'Feelings influence social behavior.','original'),
('120.9.b.3.B ',4,'Responding to a coworker''s mistake with calm feedback instead of insults helps:','["maintain a respectful working relationship", "end the job", "hide the problem", "create conflict"]'::jsonb,0,'Respectful feedback builds trust.','original'),
('120.9.b.3.C ',3,'Which shows empathy through action?','["complaining about volunteers", "volunteering at a shelter after learning about families in need", "telling people to solve it alone", "ignoring news"]'::jsonb,1,'Acts of service show empathy.','original'),
('120.9.b.3.C ',4,'Active listening is an empathy strategy because it:','["ends discussion", "lets you talk more", "helps you understand another person''s experience", "avoids their feelings"]'::jsonb,2,'Listening builds understanding.','original'),
('120.9.b.4.A ',4,'A local effect of one person''s decision to volunteer at a food bank is that:','["it increases hunger", "it has no effect", "it hurts neighbors", "it can help families in the community"]'::jsonb,3,'Personal actions affect communities.','original'),
('120.9.b.4.A ',4,'Choosing to recycle consistently shows how personal actions can affect:','["the local and global community", "only your room", "only adults", "no one"]'::jsonb,0,'Individual choices add up.','original'),
('120.9.b.4.B ',3,'Which is a responsibility of citizenship in a community?','["ignoring public meetings always", "obeying laws and participating in civic life", "breaking local laws", "refusing to cooperate"]'::jsonb,1,'Citizens take part and follow rules.','original'),
('120.9.b.4.B ',4,'Serving on a jury when called is an example of:','["a luxury", "a punishment", "a civic duty", "a hobby"]'::jsonb,2,'Jury service is a duty of citizens.','original'),
('120.9.b.4.C',4,'Mediation is a way to resolve conflict in which:','["one side forces the other", "a judge always decides", "everyone shouts", "a neutral person helps both sides reach an agreement"]'::jsonb,3,'Mediators guide discussion.','original'),
('120.9.b.4.D ',4,'A constructive dialogue with someone who holds a different viewpoint includes:','["listening carefully and asking respectful questions", "insulting", "interrupting", "ending the talk quickly"]'::jsonb,0,'Respectful listening supports dialogue.','original'),
('120.9.b.4.D ',4,'Which statement keeps a disagreement constructive?','["No one cares what you think.", "I see your point; here is how I see it.", "I refuse to listen.", "You are wrong and always have been."]'::jsonb,1,'Acknowledging the other view keeps talk respectful.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Other Texas Essential Knowledge and Skills' and d.language = 'en'
